import{_ as p,a0 as o,w as l,s as d,ao as r,I as i,x as n,a1 as e,A as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"命令行技巧：分割文件内容 | LCTT x X-CMD","titleTemplate":false,"description":"命令行技巧：分割文件内容 | LCTT (201905) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"命令行技巧：分割文件内容 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"命令行技巧：分割文件内容 | LCTT (201905) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201905/20190405 Command line quick tips- Cutting content out of files","title":"命令行技巧：分割文件内容","tag":"201905","desc":""},"relativePath":"201905/20190405 Command line quick tips- Cutting content out of files.md","filePath":"[post].md"}'),c={name:"201905/20190405 Command line quick tips- Cutting content out of files.md"};function u(g,s,h,m,f,k){const a=o("Link");return l(),d("div",null,[s[15]||(s[15]=r(`<h1 id="命令行技巧-分割文件内容" tabindex="-1">命令行技巧：分割文件内容 <a class="header-anchor" href="#命令行技巧-分割文件内容" aria-label="Permalink to “命令行技巧：分割文件内容”">​</a></h1><p><img src="https://fedoramagazine.org/wp-content/uploads/2019/04/commandline-cutting-816x345.jpg" alt=""></p><p>Fedora 发行版是一个功能齐全的操作系统，有出色的图形化桌面环境。用户可以很容易地通过单击动作来完成任何典型任务。所有这些美妙的易用性掩盖了其底层强大的命令行细节。本文是向你展示一些常见命令行实用程序的系列文章的一部分。让我们进入 shell 来看看 <code>cut</code>。</p><p>通常，当你在命令行中工作时，你处理的是文本文件。有时这些文件可能很长，虽然可以完整地阅读它们，但是可能会耗费大量时间，并且容易出错。在本文中，你将学习如何从文本文件中提取内容，并从中获取你所需的信息。</p><p>重要的是要意识到，在 Fedora 中有许多方法可以完成类似的命令行任务。例如，Fedora 仓库含有用于解析和处理文本的完整语言系统。此外，还有多个命令行实用程序可用于 shell 中任何可能的用途。本文只关注使用其中几个实用程序选项，从文件中提取一些信息并以可读的格式呈现。</p><h3 id="cut-使用" tabindex="-1">cut 使用 <a class="header-anchor" href="#cut-使用" aria-label="Permalink to “cut 使用”">​</a></h3><p>为了演示这个例子，在系统上使用一个标准的大文件，如 <code>/etc/passwd</code>。正如本系列的前一篇文章所示，你可以执行 <code>cat</code> 命令来查看整个文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat /etc/passwd</span></span>
<span class="line"><span>root:x:0:0:root:/root:/bin/bash</span></span>
<span class="line"><span>bin:x:1:1:bin:/bin:/sbin/nologin</span></span>
<span class="line"><span>daemon:x:2:2:daemon:/sbin:/sbin/nologin</span></span>
<span class="line"><span>adm:x:3:4:adm:/var/adm:/sbin/nologin</span></span>
<span class="line"><span>...</span></span></code></pre></div><p>此文件包含系统上所有所有账户的信息。它有一个特定的格式：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>name:password:user-id:group-id:comment:home-directory:shell</span></span></code></pre></div><p>假设你只想要系统上所有账户名的列表，如果你只能从每一行中删除 “name” 值。这就是 <code>cut</code> 命令派上用场的地方！它一次处理一行输入，并提取该行的特定部分。</p><p><code>cut</code> 命令提供了以不同方式选择一行的部分的选项，在本示例中需要两个，<code>-d</code> 和 <code>-f</code>。<code>-d</code> 选项允许你声明用于分隔行中值的分隔符。在本例中，冒号（<code>:</code>）用于分隔值。<code>-f</code> 选项允许你选择要提取哪些字段值。因此，在本例中，输入的命令是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cut -d: -f1 /etc/passwd</span></span>
<span class="line"><span>root</span></span>
<span class="line"><span>bin</span></span>
<span class="line"><span>daemon</span></span>
<span class="line"><span>adm</span></span>
<span class="line"><span>...</span></span></code></pre></div><p>太棒了，成功了！但是你将输出打印到标准输出，在终端会话中意味着它需要占据屏幕。如果你需要稍后完成另一项任务所需的信息，这该怎么办？如果有办法将 <code>cut</code> 命令的输出保存到文本文件中，那就太好了。对于这样的任务，shell 有一个简单的内置功能，重定向功能（<code>&gt;</code>）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cut -d: -f1 /etc/passwd &gt; names.txt</span></span></code></pre></div><p>这会将 <code>cut</code> 的输出放到一个名为 <code>names.txt</code> 的文件中，你可以使用 <code>cat</code> 来查看它的内容:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat names.txt</span></span>
<span class="line"><span>root</span></span>
<span class="line"><span>bin</span></span>
<span class="line"><span>daemon</span></span>
<span class="line"><span>adm</span></span>
<span class="line"><span>...</span></span></code></pre></div><p>使用两个命令和一个 shell 功能，可以很容易地使用 <code>cat</code> 从一个文件进行识别、提取和重定向一些信息，并将其保存到另一个文件以供以后使用。</p><hr>`,19)),i("p",null,[s[1]||(s[1]=n("via: ",-1)),e(a,{href:"https://fedoramagazine.org/command-line-quick-tips-cutting-content-out-of-files/"},{default:t(()=>[...s[0]||(s[0]=[n("https://fedoramagazine.org/command-line-quick-tips-cutting-content-out-of-files/",-1)])]),_:1})]),i("p",null,[s[6]||(s[6]=n("作者：",-1)),e(a,{href:"https://fedoramagazine.org/author/jakfrost/"},{default:t(()=>[...s[2]||(s[2]=[n("Stephen Snow",-1)])]),_:1}),s[7]||(s[7]=n(" 选题：",-1)),e(a,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[3]||(s[3]=[n("lujun9972",-1)])]),_:1}),s[8]||(s[8]=n(" 译者：",-1)),e(a,{href:"https://github.com/MjSeven"},{default:t(()=>[...s[4]||(s[4]=[n("MjSeven",-1)])]),_:1}),s[9]||(s[9]=n(" 校对：",-1)),e(a,{href:"https://github.com/wxy"},{default:t(()=>[...s[5]||(s[5]=[n("wxy",-1)])]),_:1})]),i("p",null,[s[12]||(s[12]=n("本文由 ",-1)),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[10]||(s[10]=[n("LCTT",-1)])]),_:1}),s[13]||(s[13]=n(" 原创编译，",-1)),e(a,{href:"https://linux.cn/"},{default:t(()=>[...s[11]||(s[11]=[n("Linux中国",-1)])]),_:1}),s[14]||(s[14]=n(" 荣誉推出",-1))])])}const T=p(c,[["render",u]]);export{x as __pageData,T as default};
